<script setup lang="ts">
import {computed,ref,onBeforeUnmount} from 'vue'
import {ElMessage} from 'element-plus'
import {RefreshCw,Search,RotateCcw,Eye,UserRound,BookOpen,ClipboardCheck,ShieldCheck} from 'lucide-vue-next'
import {request} from './api'
import {auditActionLabel} from '../../shared/audit'
import RecordIdentifier from './RecordIdentifier.vue'
import LearningCollections from './LearningCollections.vue'
import ProductDocument from './ProductDocument.vue'
const visible=ref(false),user=ref<any>(),exams=ref<any[]>([]),examId=ref(''),tab=ref('overview'),studyTab=ref('visits'),busy=ref(false),error=ref(''),data=ref<any>(),page=ref(1),search=ref(''),dates=ref<string[]>([]),visitKind=ref(''),orderStatus=ref('')
const detail=ref<any>(),detailOpen=ref(false),detailBusy=ref(false),detailKind=ref(''),detailError=ref('')
const collections=ref<InstanceType<typeof LearningCollections>|null>(null),collectionKey=ref(0)
const scopeMembership=ref<any>(),membershipError=ref(false)
let membershipScope='',membershipRevision=0
const levels:Record<string,string>={free:'普通会员',vip:'VIP',svip:'SVIP',trial:'体验会员'}
const states:Record<string,string>={active:'有效授予',pending:'待生效',expired:'已到期',revoked:'已撤销'}
const statuses:Record<string,string>={pending_payment:'待支付',paid:'已支付',closed:'已关闭',refunding:'待线下退款',refunded:'已退款',payment_failed:'支付失败',success:'成功',failure:'失败'}
const kinds:Record<string,string>={subject:'科目正文',chapter:'章正文',section:'节正文',knowledge:'知识点',course:'课程'}
const fmt=(v:any)=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'未记录'
const money=(v:any)=>'¥'+(Number(v||0)/100).toFixed(2)
const position=(v:any)=>v==null?'未记录':`${Math.floor(Number(v)/60)}分${Math.floor(Number(v)%60)}秒`
const examName=computed(()=>exams.value.find(e=>e.id===examId.value)?.name||'请选择考试')
const base=computed(()=>'/admin/user-profiles/'+encodeURIComponent(user.value?.id||''))
const scopeUrl=computed(()=>base.value+'/exams/'+encodeURIComponent(examId.value))
const collectionActive=computed(()=>tab.value==='learning'&&studyTab.value!=='visits')
const accountOnly=computed(()=>tab.value==='account')
const stats=computed(()=>data.value?.summary?[{label:'学习天数',value:data.value.summary.study_days,unit:'天',icon:BookOpen},{label:'内容访问',value:data.value.summary.visits,unit:'次',icon:Eye},{label:'答题提交',value:data.value.summary.answers,unit:'次',icon:ClipboardCheck},{label:'错题本',value:data.value.summary.wrong,unit:'题',icon:BookOpen},{label:'收藏',value:data.value.summary.favorites,unit:'条',icon:BookOpen},{label:'笔记',value:data.value.summary.notes,unit:'篇',icon:BookOpen}]:[])
let revision=0,openRevision=0,detailRevision=0
async function open(id:string){
 const rev=++openRevision;revision++;visible.value=true;user.value=undefined;exams.value=[];examId.value='';data.value=undefined;error.value='';busy.value=true;tab.value='overview';studyTab.value='visits';detailOpen.value=false;page.value=1;search.value='';dates.value=[]
 try{const result=await request('/admin/user-profiles/'+encodeURIComponent(id));if(rev!==openRevision)return;user.value=result.user;exams.value=result.exams;examId.value=result.exams[0]?.id||'';await load()}catch(e:any){if(rev===openRevision){error.value=e.message;busy.value=false}}
}
async function load(){
 const rev=++revision;data.value=undefined;error.value=''
 if(!user.value||(!examId.value&&!accountOnly.value)){busy.value=false;return}
 if(membershipScope!==scopeUrl.value){membershipRevision++;membershipScope=scopeUrl.value;scopeMembership.value=undefined;membershipError.value=false}
 if(examId.value&&tab.value!=='overview'&&!scopeMembership.value)void loadMembership()
 if(collectionActive.value){busy.value=false;collectionKey.value++;return}
 if(tab.value==='plan'){busy.value=false;return}
 busy.value=true
 try{
  const params=new URLSearchParams({page:String(page.value),search:search.value})
  if(tab.value==='learning'){params.set('kind',visitKind.value);if(dates.value?.length===2){params.set('from',dates.value[0]);params.set('to',dates.value[1])}}
  if(tab.value==='orders')params.set('status',orderStatus.value)
  const endpoint=tab.value==='account'?base.value+'/account-logs':scopeUrl.value+'/'+(tab.value==='learning'?'visits':tab.value)
  const result=await request(endpoint+'?'+params);if(rev===revision&&visible.value){data.value=result;if(result.current){scopeMembership.value=result.current;membershipError.value=false}}
 }catch(e:any){if(rev===revision){error.value=e.message;if(tab.value==='overview')membershipError.value=true}}finally{if(rev===revision)busy.value=false}
}
async function loadMembership(){
 const rev=++membershipRevision,scope=scopeUrl.value;membershipError.value=false
 try{const result=await request(scope+'/overview');if(rev===membershipRevision&&scope===scopeUrl.value&&visible.value)scopeMembership.value=result.current}
 catch{if(rev===membershipRevision&&scope===scopeUrl.value&&visible.value)membershipError.value=true}
}
function refresh(){membershipRevision++;scopeMembership.value=undefined;membershipError.value=false;void load()}
function changeContext(){revision++;detailRevision++;detailOpen.value=false;detail.value=undefined;page.value=1;search.value='';dates.value=[];visitKind.value='';orderStatus.value='';void load()}
function query(){page.value=1;void load()}
function reset(){search.value='';dates.value=[];visitKind.value='';orderStatus.value='';query()}
async function inspectOrder(row:any){const rev=++detailRevision;detailKind.value='order';detail.value=undefined;detailError.value='';detailOpen.value=true;detailBusy.value=true;try{const result=await request(scopeUrl.value+'/orders/'+encodeURIComponent(row.id));if(rev===detailRevision)detail.value=result}catch(e:any){if(rev===detailRevision)detailError.value=e.message}finally{if(rev===detailRevision)detailBusy.value=false}}
function inspectVisit(row:any){detailRevision++;detailKind.value='visit';detail.value=row;detailError.value='';detailBusy.value=false;detailOpen.value=true}
function close(){revision++;openRevision++;detailRevision++;membershipRevision++;membershipScope='';scopeMembership.value=undefined;detailOpen.value=false;data.value=undefined}
function eventText(row:any){const d=row.details||{};return row.action==='entitlement.adjust'?`${levels[d.before?.level]||'未记录'} → ${levels[d.after?.level]||'未记录'} · ${d.reason||''}`:d.reason||row.reason||(row.enabled===true?'启用':row.enabled===false?'停用':'—')}
onBeforeUnmount(close)
defineExpose({open})
</script>
<template>
 <el-drawer v-model="visible" title="用户档案" size="min(1380px, 96vw)" class="user-profile-drawer" :close-on-click-modal="false" destroy-on-close @close="close">
  <div class="user-profile">
   <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
   <template v-if="user">
    <header class="profile-heading"><div class="profile-avatar"><UserRound :size="28"/></div><div class="profile-identity"><h2>{{user.nickname}}<el-tag :type="user.enabled?'success':'info'">{{user.enabled?'正常':'停用'}}</el-tag><el-tag v-if="user.is_developer" type="warning">开发者</el-tag></h2><p>{{user.phone}}</p></div><el-tooltip content="刷新档案"><el-button circle aria-label="刷新档案" :loading="busy" @click="refresh"><RefreshCw :size="17"/></el-button></el-tooltip></header>
    <div class="account-facts"><span>注册时间 <b>{{fmt(user.created_at)}}</b></span><span>最近登录 <b>{{fmt(user.last_login_at)}}</b></span><span>推荐人 <b>{{user.inviter_name||'未绑定'}}{{user.inviter_phone?' · '+user.inviter_phone:''}}</b></span></div>
    <RecordIdentifier :id="user.id" table="users"/>
    <div class="profile-scope"><label for="profile-exam">考试项目</label><el-select id="profile-exam" v-model="examId" filterable aria-label="档案考试项目" placeholder="请选择考试" @change="changeContext"><el-option v-for="e in exams" :key="e.id" :value="e.id" :label="e.name"><span>{{e.name}}</span><small class="exam-option-meta">{{e.has_records?'有记录':'暂无记录'}}{{e.enabled?'':' · 已停用'}}</small></el-option></el-select><span v-if="examId" class="scope-membership" role="status" aria-live="polite"><el-tag v-if="scopeMembership" effect="light" :type="scopeMembership.level==='free'?'info':scopeMembership.level==='svip'?'warning':'primary'">当前权益：{{levels[scopeMembership.level]}}{{scopeMembership.trial?'（体验）':''}}</el-tag><span v-else class="muted">{{membershipError?'权益加载失败，请刷新':'权益加载中…'}}</span></span></div>
    <el-tabs v-model="tab" class="profile-tabs" @tab-change="changeContext"><el-tab-pane label="用户概览" name="overview"/><el-tab-pane label="学习数据" name="learning"/><el-tab-pane label="章节掌握" name="mastery"/><el-tab-pane label="购买记录" name="orders"/><el-tab-pane label="权益履约" name="fulfillment"/><el-tab-pane label="推荐关系" name="relations"/><el-tab-pane label="学习计划" name="plan"/><el-tab-pane label="账号管理记录" name="account"/></el-tabs>
    <el-empty v-if="!examId&&!accountOnly" description="暂无可选考试项目"/>
    <div v-else v-loading="busy" class="profile-content">
     <template v-if="tab==='overview'&&data">
      <div class="profile-metrics"><div v-for="(m,i) in stats" :key="m.label" :class="'metric-'+i"><span>{{m.label}}</span><strong>{{m.value}}<small>{{m.unit}}</small></strong></div></div>
      <div class="overview-columns"><section><h3><ShieldCheck :size="18"/>当前考试权益</h3><div class="rights-level">{{levels[data.current.level]}}<el-tag v-if="data.current.trial" type="warning">体验</el-tag></div><dl><div><dt>来源</dt><dd>{{data.current.source==='manual'?'人工设置':data.current.level==='free'?'默认权益':'订单权益'}}</dd></div><div><dt>有效至</dt><dd>{{data.current.expiresAt?fmt(data.current.expiresAt):'无付费权益有效期'}}</dd></div><div><dt>最近学习</dt><dd>{{fmt(data.summary.last_studied_at)}}</dd></div></dl></section><section><h3>当前考试购买情况</h3><dl><div><dt>订单总数</dt><dd>{{data.orders.total}} 笔</dd></div><div><dt>已支付订单</dt><dd>{{data.orders.paid}} 笔</dd></div><div><dt>累计支付（含已退款）</dt><dd>{{money(data.orders.paid_cents)}}</dd></div><div><dt>已确认退款</dt><dd>{{money(data.orders.refunded_cents)}}</dd></div></dl></section></div>
      <section class="profile-section"><h3>体验资格 <el-tag :type="data.trial.eligible?'success':'info'">{{data.trial.eligible?'符合资格':'不可体验'}}</el-tag></h3><p>{{data.trial.reason}}</p><small class="muted">体验次数按账号终身计算，不因切换考试或考期重置。</small></section>
     </template>
     <template v-if="tab==='learning'">
      <el-tabs v-model="studyTab" @tab-change="changeContext"><el-tab-pane label="学习记录" name="visits"/><el-tab-pane label="答题记录" name="answers"/><el-tab-pane label="错题本" name="wrong"/><el-tab-pane label="收藏" name="favorites"/><el-tab-pane label="笔记" name="notes"/></el-tabs>
      <LearningCollections v-if="collectionActive" ref="collections" :key="user.id+examId+studyTab+collectionKey" :kind="studyTab" :exams="exams" :scope-url="scopeUrl"/>
      <template v-else>
       <form class="admin-filters" @submit.prevent="query"><label class="admin-filter-field"><span>内容标题</span><el-input v-model="search" aria-label="学习内容标题" clearable/></label><label class="admin-filter-field"><span>内容类型</span><el-select v-model="visitKind" :empty-values="[null,undefined]" aria-label="学习内容类型"><el-option label="全部类型" value=""/><el-option v-for="(name,key) in kinds" :key="key" :label="name" :value="key"/></el-select></label><label class="admin-filter-field profile-date"><span>访问时间</span><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" range-separator="至"/></label><div class="admin-filter-actions"><el-button type="primary" native-type="submit"><Search :size="16"/>查询</el-button><el-button @click="reset"><RotateCcw :size="16"/>重置</el-button></div></form>
       <el-table :data="data?.items||[]"><template #empty><el-empty description="该考试暂无匹配的学习记录" :image-size="70"/></template><el-table-column label="学习内容" min-width="280"><template #default="{row}"><button class="table-title" @click="inspectVisit(row)">{{row.title}}</button><small class="cell-sub">{{row.path.join(' / ')}}</small></template></el-table-column><el-table-column label="类型" width="110"><template #default="{row}">{{kinds[row.kind]}}</template></el-table-column><el-table-column label="访问时间" width="180"><template #default="{row}">{{fmt(row.started_at)}}</template></el-table-column><el-table-column label="最近上报位置" width="150"><template #default="{row}">{{position(row.position_seconds)}}</template></el-table-column><el-table-column label="操作" width="75" fixed="right"><template #default="{row}"><el-tooltip content="查看学习记录"><el-button link type="primary" aria-label="查看学习记录" @click="inspectVisit(row)"><Eye :size="17"/></el-button></el-tooltip></template></el-table-column></el-table>
      </template>
     </template>
     <template v-if="tab==='mastery'">
      <div class="mastery-key"><span>答题覆盖率 = 已答题 / 当前可学题目</span><span>最近正确率 = 最近一次客观判分正确 / 已有客观判分题目</span></div>
      <el-table :data="data?.items||[]" row-key="id" :tree-props="{children:'children'}" :expand-row-keys="(data?.items||[]).map((r:any)=>r.id)"><template #empty><el-empty description="该考试暂无已发布章节" :image-size="70"/></template><el-table-column prop="title" label="科目 / 章 / 节" min-width="310" show-overflow-tooltip/><el-table-column prop="total" label="题目总数" width="100"/><el-table-column prop="answered" label="已答题数" width="100"/><el-table-column label="答题覆盖率" min-width="150"><template #default="{row}"><el-progress v-if="row.total" :percentage="row.coverage" :stroke-width="6"/><span v-else class="muted">暂无题目</span></template></el-table-column><el-table-column label="最近正确率" min-width="150"><template #default="{row}"><el-progress v-if="row.accuracy!=null" :percentage="row.accuracy" :stroke-width="6" color="#18a77b"/><span v-else class="muted">{{row.answered?'暂无客观判分':'未练习'}}</span></template></el-table-column><el-table-column prop="wrong" label="错题本题数" width="110"/></el-table>
     </template>
     <template v-if="tab==='orders'">
      <form class="admin-filters" @submit.prevent="query"><label class="admin-filter-field"><span>商品 / 订单号</span><el-input v-model="search" aria-label="商品或订单号" clearable/></label><label class="admin-filter-field"><span>订单状态</span><el-select v-model="orderStatus" aria-label="订单状态" :empty-values="[null,undefined]"><el-option label="全部状态" value=""/><el-option v-for="key in ['pending_payment','paid','closed','refunding','refunded']" :key="key" :label="statuses[key]" :value="key"/></el-select></label><div class="admin-filter-actions"><el-button type="primary" native-type="submit"><Search :size="16"/>查询</el-button><el-button @click="reset"><RotateCcw :size="16"/>重置</el-button></div></form>
      <el-table :data="data?.items||[]"><template #empty><el-empty description="该考试暂无匹配的购买记录" :image-size="70"/></template><el-table-column prop="product_title" label="后台商品名称" min-width="260" show-overflow-tooltip/><el-table-column label="状态" width="120"><template #default="{row}"><el-tag :type="row.status==='paid'?'success':'info'">{{statuses[row.display_status]}}</el-tag></template></el-table-column><el-table-column label="实付金额" width="130"><template #default="{row}">{{row.paid_at?money(row.amount_cents):'未支付'}}</template></el-table-column><el-table-column label="创建时间" width="180"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column><el-table-column label="支付时间" width="180"><template #default="{row}">{{fmt(row.paid_at)}}</template></el-table-column><el-table-column label="操作" width="75" fixed="right"><template #default="{row}"><el-tooltip content="查看订单"><el-button link type="primary" aria-label="查看订单" @click="inspectOrder(row)"><Eye :size="17"/></el-button></el-tooltip></template></el-table-column></el-table>
     </template>
     <template v-if="tab==='fulfillment'&&data">
      <div class="fulfillment-current"><ShieldCheck :size="24"/><div><strong>当前生效：{{levels[data.current.level]}}{{data.current.trial?' · 体验':''}}</strong><p>{{data.current.source==='manual'?'人工设置优先于订单权益':'按有效订单权益计算'}} · {{data.current.expiresAt?'有效至 '+fmt(data.current.expiresAt):'无付费有效期'}}</p></div></div>
      <section v-if="data.manual" class="profile-section"><h3>当前人工设置 <el-tag :type="data.manual.active?'success':'info'">{{data.manual.revoked?'已恢复订单权益':data.manual.active?'生效中':'未生效或已到期'}}</el-tag></h3><p>{{levels[data.manual.level]}} · {{data.manual.year}} 年考期 · {{data.manual.reason}}</p><small>{{fmt(data.manual.updated_at)}} 至 {{fmt(data.manual.ends_at)}}</small></section>
      <h3>订单权益授予</h3><el-table :data="data.grants"><template #empty><el-empty description="该考试暂无订单权益授予" :image-size="70"/></template><el-table-column label="来源商品" min-width="240"><template #default="{row}">{{row.title||'历史权益订单'}}<small v-if="row.deleted_at" class="cell-sub">测试订单已删除</small></template></el-table-column><el-table-column label="档位 / 考期" width="145"><template #default="{row}">{{levels[row.trial_level||row.level]}}<small class="cell-sub">{{row.year}} 年{{row.level==='trial'?' · 体验':''}}</small></template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.state==='active'?'success':'info'">{{states[row.state]}}</el-tag></template></el-table-column><el-table-column label="生效时间" width="180"><template #default="{row}">{{fmt(row.starts_at)}}</template></el-table-column><el-table-column label="到期时间" width="180"><template #default="{row}">{{fmt(row.ends_at)}}</template></el-table-column><el-table-column label="操作" width="75" fixed="right"><template #default="{row}"><el-tooltip :content="row.deleted_at?'原测试订单已删除':'查看来源订单'"><el-button link type="primary" :disabled="!!row.deleted_at" aria-label="查看来源订单" @click="inspectOrder({id:row.order_id})"><Eye :size="17"/></el-button></el-tooltip></template></el-table-column></el-table>
      <section class="profile-section"><h3>权益与订单变更记录（最近100条）</h3><el-table :data="data.history" empty-text="该考试暂无变更记录"><el-table-column label="操作" min-width="160"><template #default="{row}">{{auditActionLabel(row.action)}}</template></el-table-column><el-table-column label="变更 / 原因" min-width="300"><template #default="{row}">{{eventText(row)}}</template></el-table-column><el-table-column prop="actor_name" label="操作人" width="120"/><el-table-column label="时间" width="180"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column></el-table></section>
     </template>
     <template v-if="tab==='relations'&&data">
      <section class="profile-section"><h3>账号推荐关系</h3><el-descriptions :column="1" border><el-descriptions-item label="推荐人">{{user.inviter_name||'未绑定'}}{{user.inviter_phone?' · '+user.inviter_phone:''}}</el-descriptions-item><el-descriptions-item label="推荐人邀请码">{{user.inviter_code||'无'}}</el-descriptions-item><el-descriptions-item label="绑定时间">未记录</el-descriptions-item><el-descriptions-item label="本人邀请码">{{user.invite_code}}</el-descriptions-item></el-descriptions></section>
      <section class="profile-section"><h3>当前考试使用的运营推荐码</h3><el-table :data="data.uses" empty-text="该考试暂无推荐码使用记录"><el-table-column prop="code" label="推荐码"/><el-table-column label="使用时间" min-width="180"><template #default="{row}">{{fmt(row.used_at)}}</template></el-table-column><el-table-column label="赠送权益记录"><template #default="{row}">{{levels[row.permission_level]||'未赠送'}}</template></el-table-column></el-table></section>
      <section class="profile-section"><h3>已推荐且在当前考试有记录的用户</h3><el-table :data="data.invited" empty-text="该考试暂无被推荐用户"><el-table-column prop="nickname" label="用户"/><el-table-column prop="phone" label="手机号"/><el-table-column label="注册时间" min-width="180"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column></el-table></section>
     </template>
     <el-empty v-if="tab==='plan'" description="等待开发" :image-size="90"/>
     <template v-if="tab==='account'"><p class="muted">账号设置不区分考试；当前考试的权益调整记录在“权益履约”中查看。</p><el-table :data="data?.items||[]"><template #empty><el-empty description="暂无账号管理记录" :image-size="70"/></template><el-table-column label="操作" min-width="170"><template #default="{row}">{{auditActionLabel(row.action)}}</template></el-table-column><el-table-column label="内容" min-width="220"><template #default="{row}">{{eventText(row)}}</template></el-table-column><el-table-column prop="actor_name" label="操作人" width="140"/><el-table-column label="时间" width="180"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column></el-table></template>
     <div v-if="data?.total!=null&&!collectionActive" class="pagination"><span>共 {{data.total}} 条</span><el-pagination v-model:current-page="page" :total="data.total" :page-size="20" layout="prev,pager,next" @current-change="load"/></div>
    </div>
   </template>
   <el-skeleton v-else-if="busy" :rows="8" animated/>
  </div>
 </el-drawer>
 <el-drawer v-model="detailOpen" :title="detailKind==='order'?'订单详情':'学习记录详情'" size="min(760px, 100vw)" :close-on-click-modal="false" append-to-body @close="detailRevision++">
  <div v-loading="detailBusy" class="profile-detail"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false"/>
   <template v-if="detail&&detailKind==='visit'"><h3>{{detail.title}}</h3><p>{{detail.path.join(' / ')}}</p><el-descriptions :column="1" border><el-descriptions-item label="考试">{{examName}}</el-descriptions-item><el-descriptions-item label="内容类型">{{kinds[detail.kind]}}</el-descriptions-item><el-descriptions-item label="访问时间">{{fmt(detail.started_at)}}</el-descriptions-item><el-descriptions-item label="最近上报">{{fmt(detail.last_activity_at)}}</el-descriptions-item><el-descriptions-item label="播放位置">{{position(detail.position_seconds)}}</el-descriptions-item><el-descriptions-item label="媒体总时长">{{position(detail.duration_seconds)}}</el-descriptions-item></el-descriptions></template>
   <template v-if="detail&&detailKind==='order'"><h3>{{detail.order.product_title}}</h3><el-descriptions :column="1" border><el-descriptions-item label="订单号">{{detail.order.id}}</el-descriptions-item><el-descriptions-item label="考试 / 考期">{{detail.order.exam_name}} · {{detail.order.cycle_year}} 年</el-descriptions-item><el-descriptions-item label="权益档位">{{levels[detail.order.entitlement_level]}}</el-descriptions-item><el-descriptions-item label="订单状态">{{statuses[detail.order.display_status]}}</el-descriptions-item><el-descriptions-item label="商品金额">{{money(detail.order.amount_cents)}}</el-descriptions-item><el-descriptions-item label="支付时间">{{fmt(detail.order.paid_at)}}</el-descriptions-item><el-descriptions-item label="退款原因">{{detail.order.refund_reason||'无'}}</el-descriptions-item><el-descriptions-item label="退款凭证">{{detail.order.refund_reference||'无'}}</el-descriptions-item><el-descriptions-item label="权益有效期">{{fmt(detail.order.entitlement_starts_at)}} 至 {{fmt(detail.order.entitlement_ends_at)}}</el-descriptions-item></el-descriptions>
    <section class="profile-section"><h3>下单时的商品详情</h3><ProductDocument v-if="detail.order.product_snapshot?.document" :document="detail.order.product_snapshot.document"/><p v-else class="muted">未记录商品图文快照</p></section>
    <section class="profile-section"><h3>支付记录</h3><el-table :data="detail.payments" empty-text="暂无支付记录"><el-table-column label="支付结果"><template #default="{row}">{{statuses[row.status]||row.status}}</template></el-table-column><el-table-column prop="method" label="支付方式"/><el-table-column label="时间" min-width="180"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column></el-table></section>
    <section class="profile-section"><h3>订单变更记录</h3><el-table :data="detail.history" empty-text="暂无变更记录"><el-table-column label="操作"><template #default="{row}">{{auditActionLabel(row.action)}}</template></el-table-column><el-table-column label="原因"><template #default="{row}">{{row.details.reason||'无'}}</template></el-table-column><el-table-column label="时间" min-width="180"><template #default="{row}">{{fmt(row.created_at)}}</template></el-table-column></el-table></section>
   </template>
  </div><template #footer><el-button @click="detailOpen=false">关闭</el-button></template>
 </el-drawer>
</template>
<style scoped>
.user-profile{min-width:0}.profile-heading{display:flex;align-items:center;gap:16px}.profile-avatar{width:56px;height:56px;flex:none;border-radius:8px;display:grid;place-items:center;background:var(--el-color-primary-light-9);color:var(--el-color-primary)}.profile-identity{flex:1;min-width:0}.profile-identity h2{display:flex;flex-wrap:wrap;align-items:center;gap:10px;font-size:22px;margin:0;overflow-wrap:anywhere}.profile-identity p{margin:8px 0 0;color:var(--el-text-color-regular)}.account-facts{display:flex;flex-wrap:wrap;gap:12px 28px;margin:20px 0;color:var(--el-text-color-secondary);font-size:12px}.account-facts b{color:var(--el-text-color-regular);font-weight:400;margin-left:8px}.profile-scope{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:16px 0;margin:10px 0;border-top:1px solid var(--admin-border)}.profile-scope label{font-size:13px;font-weight:600}.profile-scope .el-select{width:300px;max-width:100%}.exam-option-meta{margin-left:12px;color:var(--el-text-color-secondary)}.profile-content{min-height:280px}.profile-tabs :deep(.el-tabs__item){font-weight:600}.profile-metrics{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));padding:24px 0;border-bottom:1px solid var(--admin-border);gap:16px}.profile-metrics span{font-size:13px;color:var(--el-text-color-regular)}.profile-metrics strong{display:block;font-size:28px;margin-top:12px;font-variant-numeric:tabular-nums}.profile-metrics small{font-size:12px;margin-left:8px;font-weight:400;color:var(--el-text-color-secondary)}.metric-1 strong,.metric-4 strong{color:var(--el-color-primary)}.metric-2 strong,.metric-5 strong{color:#138566}.metric-3 strong{color:#c58126}.overview-columns{display:grid;grid-template-columns:1fr 1fr;gap:40px;padding:24px 0}.overview-columns h3,.profile-section h3{display:flex;align-items:center;gap:10px;margin:0 0 16px;font-size:15px}.overview-columns dl{font-size:13px}.overview-columns dl div{display:flex;justify-content:space-between;gap:12px;margin:16px 0}.overview-columns dt{color:var(--el-text-color-secondary)}.overview-columns dd{margin:0;text-align:right}.rights-level{font-size:22px;font-weight:650;display:flex;align-items:center;gap:10px}.profile-section{padding-top:24px;margin-top:16px;border-top:1px solid var(--admin-border)}.profile-section p{font-size:14px;line-height:1.8}.muted{color:var(--el-text-color-secondary);font-size:12px}.profile-date{min-width:0;flex-basis:280px}.profile-date :deep(.el-date-editor){width:100%;box-sizing:border-box}.mastery-key{display:flex;gap:12px 32px;flex-wrap:wrap;padding:6px 0 20px;color:var(--el-text-color-regular);font-size:12px;line-height:1.8}.fulfillment-current{display:flex;align-items:center;gap:14px;padding:20px 0;border-bottom:1px solid var(--admin-border);color:var(--el-color-primary)}.fulfillment-current p{font-size:13px;color:var(--el-text-color-regular);margin:8px 0 0}.profile-detail{min-height:180px;overflow-wrap:anywhere}.profile-detail h3{font-size:18px}.table-title{max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.cell-sub{overflow-wrap:anywhere}@media(max-width:760px){.profile-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}.overview-columns{grid-template-columns:1fr;gap:10px}.account-facts{flex-direction:column}.profile-scope>.el-tag{max-width:100%;white-space:normal;height:auto;line-height:1.8}.profile-identity h2{font-size:18px}.profile-avatar{width:44px;height:44px}.profile-metrics strong{font-size:23px}}
</style>
